// Wall layout, validation and the seeded shuffle (Spec/wall.md).

import Testing
@testable import Riichi

struct WallVector: Sendable {
    let seed: UInt64
    let hand: Int
    /// Four lines of 34 tiles, space-separated, in wall order.
    let tiles: [String]

    var wall: [Tile] { tiles.flatMap { $0.split(separator: " ").map { Tile($0)! } } }
}

/// The three test vectors of Spec/wall.md, generated by an independent
/// implementation written from the spec text.
let wallVectors: [WallVector] = [
    WallVector(seed: 0, hand: 0, tiles: [
        "3s 3z 7s 4z 5z 1s 0p 4m 9s 6z 3z 8m 2z 8p 2s 3s 3p 2m 2s 3z 6z 6m 1m 2z 5z 6p 9p 2z 7m 7p 4z 5s 9s 5p",
        "6m 4m 6z 4m 1p 4s 2p 6s 1s 3m 8m 5p 9m 1z 7s 3s 2z 3p 6s 2s 8s 6p 2p 1z 1p 2m 5s 1m 1m 4p 4p 7m 0s 4s",
        "6m 7p 1p 5p 3m 8s 6p 9p 3p 7z 7z 7z 3p 4s 6s 4s 8s 5s 3s 3m 6s 5z 4p 8m 1s 7m 9s 9p 2s 5m 8p 8p 8m 8s",
        "3z 9p 9m 1m 4p 4z 7m 5m 7s 1s 6p 1z 2m 6z 2m 7z 9m 5z 6m 4m 1p 7p 7p 2p 7s 3m 5m 9s 8p 1z 2p 0m 4z 9m",
    ]),
    WallVector(seed: 20261127, hand: 3, tiles: [
        "1z 3p 7p 3z 4z 7m 1p 2z 7m 4m 1m 4s 3m 0m 7p 4p 5m 8m 6s 9m 5s 2m 2z 7s 2m 8p 7z 2s 5s 5z 9p 9s 7p 3z",
        "9m 3s 6z 4s 8p 5m 9m 8m 4z 4s 7m 1z 1z 7s 8p 9s 1s 9s 1p 4m 1z 6z 2m 4p 7m 6p 3z 3p 6m 8m 2m 2p 6z 4z",
        "7s 3s 5p 4p 6s 3z 1p 3m 2p 1s 0p 5z 1m 5p 8s 7s 6s 3m 0s 9m 6m 7z 1m 4s 6m 2p 2p 2s 5p 4m 5m 6p 3p 5z",
        "4m 7z 2s 9p 3m 6s 3s 8s 3s 5z 1p 3p 6z 4z 7z 5s 1s 2z 2z 8m 2s 9p 1m 8p 4p 7p 8s 1s 6p 8s 6p 6m 9s 9p",
    ]),
    WallVector(seed: 18446744073709551615, hand: 7, tiles: [
        "8s 1z 3m 8p 4m 7z 3z 8m 3s 4p 8s 1s 4p 7m 6z 0p 1s 9s 7z 8m 5p 7m 5s 8p 3m 5s 2z 3z 2z 3p 3m 7z 5z 1p",
        "9s 9m 3z 7p 8m 5z 2z 1m 0m 1s 2s 9p 6p 9m 8p 5s 6s 5m 3p 4m 1z 3z 1z 6s 2m 0s 6s 2m 6p 2p 6m 1p 4z 3p",
        "3p 4z 4m 9s 5z 2p 1m 2p 4m 5z 1z 2m 6z 2m 2z 5p 5m 7s 6m 4s 9m 8s 7s 4z 3s 2s 2s 6z 4s 7z 3s 1p 7s 3s",
        "8s 3m 7p 9p 2s 7p 4p 4z 5m 8m 7m 1m 1m 9p 6m 4s 7s 7p 9p 6p 1s 8p 7m 9m 6z 2p 5p 6p 4s 4p 6s 9s 6m 1p",
    ]),
]

@Suite struct WallTests {
    @Test func splitMixKnownOutput() {
        // SplitMix64's published first output for seed 0.
        var sm = SplitMix64(state: 0)
        #expect(sm.next() == 0xE220_A839_7B1D_CDAF)
    }

    @Test func keyCheckValues() {
        // Spec/wall.md §4.
        #expect(Wall.key(seed: 0, hand: 0) == 0x06F9_D94E_6078_E18F)
        var x = Xoshiro256StarStar(seeding: Wall.key(seed: 0, hand: 0))
        #expect([x.next(), x.next(), x.next()] == [0x3B26_4D20_8BB7_BCCB, 0xB79A_3478_FDF0_C6A6, 0x8D92_42CD_86FF_675C])
        // Non-linear key mixing avoids collisions along (seed + G, hand - 1).
        #expect(Wall.key(seed: 0x9E37_79B9_7F4A_7C15, hand: 0) != Wall.key(seed: 0, hand: 1))
    }

    @Test(arguments: wallVectors) func seededWallMatchesSpec(_ v: WallVector) {
        #expect(v.wall.count == 136)
        #expect(Wall(seed: v.seed, hand: v.hand).tiles == v.wall)
    }

    @Test func sortedIsTheTileSet() {
        #expect(Wall.sorted.count == 136)
        #expect(Wall.sorted == Wall.sorted.sorted())
        #expect(Wall.sorted.count(where: \.isRed) == 3)
        let counts = Counts(Wall.sorted)
        #expect(Kind.all.allSatisfy { counts[$0] == 4 })
    }

    @Test func seededWallsAreValidAndDiffer() {
        let a = Wall(seed: 42, hand: 0), b = Wall(seed: 42, hand: 1), c = Wall(seed: 43, hand: 0)
        for w in [a, b, c] { #expect(Wall(tiles: w.tiles) == w) }
        #expect(a != b && a != c && b != c)
        #expect(Wall(seed: 42, hand: 0) == a)
    }

    @Test func validation() {
        let t = Wall.sorted
        #expect(Wall(tiles: t) != nil)
        #expect(Wall(tiles: Array(t.dropLast())) == nil)
        #expect(Wall(tiles: t + [t[0]]) == nil)
        // A plain five in place of the red one.
        var noRed = t
        noRed[noRed.firstIndex(of: Tile(Kind(.man, 5), red: true))!] = Tile(Kind(.man, 5))
        #expect(Wall(tiles: noRed) == nil)
        // A fifth copy of one kind and only three of another.
        var swapped = t
        swapped[0] = swapped[135]
        #expect(Wall(tiles: swapped) == nil)
    }

    @Test func layout() {
        let w = Wall(tiles: (0..<136).map { Wall.sorted[$0] })!
        // With the sorted wall, index i holds kind i / 4.
        func kinds(_ tiles: [Tile]) -> [Int] { tiles.map { $0.kind.index } }
        #expect(kinds(w.dealt(toDealerOffset: 0)) == [0, 0, 0, 0, 4, 4, 4, 4, 8, 8, 8, 8, 12])
        #expect(kinds(w.dealt(toDealerOffset: 3)) == [3, 3, 3, 3, 7, 7, 7, 7, 11, 11, 11, 11, 12])
        #expect(w.dealt(to: Seat(2), dealer: Seat(1)) == w.dealt(toDealerOffset: 1))
        #expect(w.dealt(to: Seat(0), dealer: Seat(1)) == w.dealt(toDealerOffset: 3))
        #expect(w.liveDraw(0) == w.tiles[52] && w.liveDraw(69) == w.tiles[121])
        #expect(w.replacement(0) == w.tiles[122] && w.replacement(3) == w.tiles[125])
        #expect(w.doraIndicator(0) == w.tiles[126] && w.doraIndicator(4) == w.tiles[130])
        #expect(w.uraIndicator(0) == w.tiles[131] && w.uraIndicator(4) == w.tiles[135])
        // Every index is used exactly once.
        var used = Seat.all.flatMap { w.dealt(to: $0, dealer: Seat(0)) }
        used += (0..<70).map(w.liveDraw) + (0..<4).map(w.replacement)
        used += (0..<5).map(w.doraIndicator) + (0..<5).map(w.uraIndicator)
        #expect(used.sorted() == Wall.sorted)
    }

    @Test func boundedSamplingStaysInRange() {
        var rng = Xoshiro256StarStar(seeding: 7)
        for bound in [1, 2, 3, 136, 1 << 40] as [UInt64] {
            for _ in 0..<1000 { #expect(rng.next(below: bound) < bound) }
        }
    }
}
